func TestAnomalyDetectionServerRewritesSuppressed(t *testing.T) {
	for _, c := range anomalyDetectionCases {
		if !diffSuppressAnomalyDetection("body", c.server, c.config, nil) {
			t.Errorf("%s: server rewrite still diffs", c.name)
		}
	}
}

func TestAnomalyDetectionRealChangesStillDiff(t *testing.T) {
	edits := map[string]func(map[string]any){
		"interval": func(m map[string]any) {
			m["detection_interval"].(map[string]any)["period"].(map[string]any)["interval"] = 10.0
		},
		"shingle": func(m map[string]any) { m["shingle_size"] = 4.0 },
		"rule": func(m map[string]any) {
			m["rules"].([]any)[0].(map[string]any)["conditions"].([]any)[0].(map[string]any)["value"] = 0.5
		},
		"filter": func(m map[string]any) {
			m["filter_query"].(map[string]any)["bool"].(map[string]any)["must_not"].([]any)[0].(map[string]any)["term"].(map[string]any)["attributes.event_type.keyword"] = "event"
		},
		"desc":    func(m map[string]any) { m["description"] = "other" },
		"feature": func(m map[string]any) { m["feature_attributes"].([]any)[1].(map[string]any)["feature_enabled"] = false },
	}
	for name, edit := range edits {
		var m map[string]any
		if err := json.Unmarshal([]byte(anomalyDetectionCases[0].config), &m); err != nil {
			t.Fatal(err)
		}
		edit(m)
		changed, _ := json.Marshal(m)
		if diffSuppressAnomalyDetection("body", anomalyDetectionCases[0].server, string(changed), nil) {
			t.Errorf("%s: real change suppressed", name)
		}
	}
}

func TestAnomalyDetectionRangeBounds(t *testing.T) {
	// gt vs gte must still differ
	srv := `{"filter_query":{"range":{"t":{"from":"a","to":null,"include_lower":false,"include_upper":true,"boost":1.0}}}}`
	if diffSuppressAnomalyDetection("body", srv, `{"filter_query":{"range":{"t":{"gte":"a"}}}}`, nil) {
		t.Error("gt read back equal to gte")
	}
	if !diffSuppressAnomalyDetection("body", srv, `{"filter_query":{"range":{"t":{"gt":"a"}}}}`, nil) {
		t.Error("gt does not match its server form")
	}
}
